import{_ as e,o as l,c as o,a0 as p,j as s,a}from"./chunks/framework.DqMqoJl9.js";const m=JSON.parse('{"title":"表单","description":"","frontmatter":{},"headers":[],"relativePath":"browser/4-form.md","filePath":"browser/4-form.md","lastUpdated":1791573371000}'),t={name:"browser/4-form.md"};function c(r,n,i,d,u,b){return l(),o("div",null,[...n[0]||(n[0]=[p(`<h1 id="表单" tabindex="-1">表单 <a class="header-anchor" href="#表单" aria-label="Permalink to &quot;表单&quot;">​</a></h1><h2 id="_1-表单属性和方法" tabindex="-1">1 表单属性和方法 <a class="header-anchor" href="#_1-表单属性和方法" aria-label="Permalink to &quot;1 表单属性和方法&quot;">​</a></h2><h3 id="_1-1-获取元素" tabindex="-1">1.1 获取元素 <a class="header-anchor" href="#_1-1-获取元素" aria-label="Permalink to &quot;1.1 获取元素&quot;">​</a></h3><p>文档中的表单是特殊集合 <code>document.forms</code> 的成员</p><p>这就是所谓的命名的集合：既是被命名了的，也是有序的。我们既可以使用名字，也可以使用在文档中的编号来获取表单</p><ul><li><code>document.forms.my</code> - <code>name = &quot;my&quot;</code> 的表单</li><li><code>document.forms[0]</code> - 文档中的第一个表单</li></ul><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">form</span><span style="color:#6F42C1;"> name</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;my&quot;</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">input</span><span style="color:#6F42C1;"> name</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;one&quot;</span><span style="color:#6F42C1;"> value</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;1&quot;</span><span style="color:#24292E;"> /&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">input</span><span style="color:#6F42C1;"> name</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;two&quot;</span><span style="color:#6F42C1;"> value</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;2&quot;</span><span style="color:#24292E;"> /&gt;</span></span>
<span class="line"><span style="color:#24292E;">&lt;/</span><span style="color:#22863A;">form</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">script</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#6A737D;">  // 获取表单</span></span>
<span class="line"><span style="color:#D73A49;">  let</span><span style="color:#24292E;"> form </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> document.forms.my; </span><span style="color:#6A737D;">// &lt;form name=&quot;my&quot;&gt; 元素</span></span>
<span class="line"><span style="color:#6A737D;">  // 获取表单中的元素</span></span>
<span class="line"><span style="color:#D73A49;">  let</span><span style="color:#24292E;"> elem </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> form.elements.one; </span><span style="color:#6A737D;">// &lt;input name=&quot;one&quot;&gt; 元素</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6F42C1;">  alert</span><span style="color:#24292E;">(elem.value); </span><span style="color:#6A737D;">// 1</span></span>
<span class="line"><span style="color:#24292E;">&lt;/</span><span style="color:#22863A;">script</span><span style="color:#24292E;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p><strong>子表单 Fieldset：</strong></p><p>一个表单内会有一个或多个 <code>&lt;fieldset&gt;</code> 元素。它们也具有 <code>elements</code> 属性，该属性列出了 <code>&lt;fieldset&gt;</code> 中的表单控件</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">body</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">form</span><span style="color:#6F42C1;"> id</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;form&quot;</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">    &lt;</span><span style="color:#22863A;">fieldset</span><span style="color:#6F42C1;"> name</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;userFields&quot;</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">      &lt;</span><span style="color:#22863A;">legend</span><span style="color:#24292E;">&gt;info&lt;/</span><span style="color:#22863A;">legend</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">      &lt;</span><span style="color:#22863A;">input</span><span style="color:#6F42C1;"> name</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;login&quot;</span><span style="color:#6F42C1;"> type</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;text&quot;</span><span style="color:#24292E;"> /&gt;</span></span>
<span class="line"><span style="color:#24292E;">    &lt;/</span><span style="color:#22863A;">fieldset</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;/</span><span style="color:#22863A;">form</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">script</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#6F42C1;">    alert</span><span style="color:#24292E;">(form.elements.login); </span><span style="color:#6A737D;">// &lt;input name=&quot;login&quot;&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D73A49;">    let</span><span style="color:#24292E;"> fieldset </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> form.elements.userFields;</span></span>
<span class="line"><span style="color:#6F42C1;">    alert</span><span style="color:#24292E;">(fieldset); </span><span style="color:#6A737D;">// HTMLFieldSetElement</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">    // 我们可以通过名字从表单和 fieldset 中获取 input</span></span>
<span class="line"><span style="color:#6F42C1;">    alert</span><span style="color:#24292E;">(fieldset.elements.login </span><span style="color:#D73A49;">==</span><span style="color:#24292E;"> form.elements.login); </span><span style="color:#6A737D;">// true</span></span>
<span class="line"><span style="color:#24292E;">  &lt;/</span><span style="color:#22863A;">script</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">&lt;/</span><span style="color:#22863A;">body</span><span style="color:#24292E;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><h3 id="_1-2-反向引用" tabindex="-1">1.2 反向引用 <a class="header-anchor" href="#_1-2-反向引用" aria-label="Permalink to &quot;1.2 反向引用&quot;">​</a></h3><p>对于任何元素，其对应的表单都可以通过 <code>element.form</code> 访问到。因此，表单引用了所有元素，元素也引用了表单</p><p><strong>例如：</strong></p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">form</span><span style="color:#6F42C1;"> id</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;form&quot;</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">input</span><span style="color:#6F42C1;"> type</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;text&quot;</span><span style="color:#6F42C1;"> name</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;login&quot;</span><span style="color:#24292E;"> /&gt;</span></span>
<span class="line"><span style="color:#24292E;">&lt;/</span><span style="color:#22863A;">form</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">script</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#6A737D;">  // form -&gt; element</span></span>
<span class="line"><span style="color:#D73A49;">  let</span><span style="color:#24292E;"> login </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> form.login;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">  // element -&gt; form</span></span>
<span class="line"><span style="color:#6F42C1;">  alert</span><span style="color:#24292E;">(login.form); </span><span style="color:#6A737D;">// HTMLFormElement</span></span>
<span class="line"><span style="color:#24292E;">&lt;/</span><span style="color:#22863A;">script</span><span style="color:#24292E;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h3 id="_1-3-表单元素" tabindex="-1">1.3 表单元素 <a class="header-anchor" href="#_1-3-表单元素" aria-label="Permalink to &quot;1.3 表单元素&quot;">​</a></h3><p><strong>input 和 textarea</strong></p><p>可以通过 <code>input.value</code>（字符串）或 <code>input.checked</code>（布尔值）来访问复选框（checkbox）的 <code>value</code></p><p><strong>select 和 option</strong></p><p>一个 <code>&lt;select&gt;</code> 元素有 3 个重要的属性：</p><ul><li><code>select.options</code> —— <code>&lt;option&gt;</code> 的子元素的集合</li><li><code>select.value</code> —— 当前所选择的 <code>&lt;option&gt;</code> 的 value</li><li><code>select.selectedIndex</code> —— 当前所选择的 <code>&lt;option&gt;</code> 的编号</li></ul><p>提供了三种为 <code>&lt;select&gt;</code> 设置 <code>value</code> 的不同方式：</p><ol><li>找到对应的 <code>&lt;option&gt;</code> 元素，并将 <code>option.selected</code> 设置为 <code>true</code></li><li>将 <code>select.value</code> 设置为对应的 <code>value</code></li><li>将 <code>select.selectedIndex</code> 设置为对应 <code>&lt;option&gt;</code> 的编号</li></ol><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">select</span><span style="color:#6F42C1;"> id</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;select&quot;</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">option</span><span style="color:#6F42C1;"> value</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;apple&quot;</span><span style="color:#24292E;">&gt;Apple&lt;/</span><span style="color:#22863A;">option</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">option</span><span style="color:#6F42C1;"> value</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;pear&quot;</span><span style="color:#24292E;">&gt;Pear&lt;/</span><span style="color:#22863A;">option</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">option</span><span style="color:#6F42C1;"> value</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;banana&quot;</span><span style="color:#24292E;">&gt;Banana&lt;/</span><span style="color:#22863A;">option</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">&lt;/</span><span style="color:#22863A;">select</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">script</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#6A737D;">  // 所有这三行做的是同一件事</span></span>
<span class="line"><span style="color:#24292E;">  select.options[</span><span style="color:#005CC5;">2</span><span style="color:#24292E;">].selected </span><span style="color:#D73A49;">=</span><span style="color:#005CC5;"> true</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">  select.selectedIndex </span><span style="color:#D73A49;">=</span><span style="color:#005CC5;"> 2</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">  select.value </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> &#39;banana&#39;</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">&lt;/</span><span style="color:#22863A;">script</span><span style="color:#24292E;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p><strong>new Option</strong></p><p>用来创建 Option 元素，较少使用</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">option </span><span style="color:#D73A49;">=</span><span style="color:#D73A49;"> new</span><span style="color:#6F42C1;"> Option</span><span style="color:#24292E;">(text, value, defaultSelected, selected);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>text</code> —— <code>&lt;option&gt;</code> 中的文本</li><li><code>value</code> —— <code>&lt;option&gt;</code> 的 value</li><li><code>defaultSelected</code> —— 如果为 true，那么 <code>selected</code> HTML-特性（attribute）就会被创建</li><li><code>selected</code> —— 如果为 true，那么这个 <code>&lt;option&gt;</code> 就会被选中</li></ul><h2 id="_2-focus-和-blur" tabindex="-1">2 focus 和 blur <a class="header-anchor" href="#_2-focus-和-blur" aria-label="Permalink to &quot;2 focus 和 blur&quot;">​</a></h2><h3 id="_2-1-事件" tabindex="-1">2.1 事件 <a class="header-anchor" href="#_2-1-事件" aria-label="Permalink to &quot;2.1 事件&quot;">​</a></h3><p>当元素聚焦时，会触发 <code>focus</code> 事件，当元素失去焦点时，会触发 <code>blur</code> 事件</p><h3 id="_2-2-方法" tabindex="-1">2.2 方法 <a class="header-anchor" href="#_2-2-方法" aria-label="Permalink to &quot;2.2 方法&quot;">​</a></h3><p><code>elem.focus()</code> 和 <code>elem.blur()</code> 方法可以设置和移除元素上的焦点</p><blockquote><p>注意，我们无法通过在 <code>onblur</code> 事件处理程序中调用 <code>event.preventDefault()</code> 来 “阻止失去焦点”，因为 <code>onblur</code> 事件处理程序是在元素失去焦点 <code>之后</code> 运行的</p></blockquote><h3 id="_2-3-tabindex" tabindex="-1">2.3 tabindex <a class="header-anchor" href="#_2-3-tabindex" aria-label="Permalink to &quot;2.3 tabindex&quot;">​</a></h3><p>默认情况下，很多元素不支持聚焦。使用 HTML-特性（attribute）<code>tabindex</code> 可以改变这种情况</p><p>任何具有 <code>tabindex</code> attribute 的元素，都会变成可聚焦的。该 attribute 的 <code>value</code> 是当使用 Tab 在元素之间进行切换时，元素的顺序号</p><p><strong>有两个特殊的值：</strong></p><ul><li><code>tabindex = &quot;0&quot;</code> 会使该元素被与那些不具有 <code>tabindex</code> 的元素放在一起。具有 <code>tabindex = &quot;0&quot;</code> 的元素将排在那些具有 <code>tabindex ≥ 1</code> 的元素的后面</li><li><code>tabindex = &quot;-1&quot;</code> 只允许以编程的方式聚焦于元素。Tab 键会忽略这样的元素，但是 <code>elem.focus()</code> 有效</li></ul><h3 id="_2-4-focus-和-blur-委托" tabindex="-1">2.4 focus 和 blur 委托 <a class="header-anchor" href="#_2-4-focus-和-blur-委托" aria-label="Permalink to &quot;2.4 focus 和 blur 委托&quot;">​</a></h3><blockquote><p><code>focus</code> 和 <code>blur</code> 事件不会向上冒泡</p></blockquote><p><strong>有两个解决方案：</strong></p><ol><li><code>focus/blur</code> 不会向上冒泡，但会在捕获阶段向下传播。将处理程序置于捕获阶段</li><li>可以使用 <code>focusin</code> 和 <code>focusout</code> 事件，与 <code>focus/blur</code> 事件完全一样，只是它们会冒泡</li></ol><h2 id="_3-事件-change-input-cut-copy-paste" tabindex="-1">3 事件 change input cut copy paste <a class="header-anchor" href="#_3-事件-change-input-cut-copy-paste" aria-label="Permalink to &quot;3 事件 change input cut copy paste&quot;">​</a></h2><h3 id="_3-1-change" tabindex="-1">3.1 change <a class="header-anchor" href="#_3-1-change" aria-label="Permalink to &quot;3.1 change&quot;">​</a></h3><p>当元素<strong>更改完成</strong>时，将触发 <code>change</code> 事件</p><ul><li>对于文本输入框，当其失去焦点时，就会触发 <code>change</code> 事件</li><li>对于其它元素：<code>select</code> <code>input type=checkbox/radio</code>，会在选项更改后立即触发 <code>change</code> 事件</li></ul><h3 id="_3-2-input" tabindex="-1">3.2 input <a class="header-anchor" href="#_3-2-input" aria-label="Permalink to &quot;3.2 input&quot;">​</a></h3><p>每当用户对输入值进行修改后，就会触发 <code>input</code> 事件</p><p>与键盘事件不同，只要值改变了，<code>input</code> 事件就会触发，即使那些不涉及键盘行为的值的更改也是如此：使用鼠标粘贴，或者使用语音识别来输入文本</p><blockquote><p>无法阻止 <code>oninput</code> 中的任何事件。当输入值更改后，就会触发 <code>input</code> 事件。所以，我们无法使用 <code>event.preventDefault()</code></p></blockquote><h3 id="_3-3-cut-copy-paste" tabindex="-1">3.3 cut copy paste <a class="header-anchor" href="#_3-3-cut-copy-paste" aria-label="Permalink to &quot;3.3 cut copy paste&quot;">​</a></h3><p>它们属于 <code>ClipboardEvent</code> 类，并提供了对 剪切/拷贝/粘贴 的数据的访问方法</p><blockquote><p>可以使用 <code>event.preventDefault()</code> 来中止行为</p></blockquote><blockquote><p>注意，在 <code>剪切/复制</code> 事件处理程序中调用 <code>event.clipboardData.getData(...)</code> 只会得到一个空字符串。从技术上讲，这是因为此时数据还未存入剪切板。如果我们使用 <code>event.preventDefault()</code>，则它根本不会被复制。使用 <code>document.getSelection()</code> 来得到被选中的文本</p></blockquote><p>另外，还有一个可以访问剪切板的异步 API：<code>navigator.clipboard</code>，火狐浏览器（Firefox）尚未支持</p><h3 id="_3-4-安全限制" tabindex="-1">3.4 安全限制 <a class="header-anchor" href="#_3-4-安全限制" aria-label="Permalink to &quot;3.4 安全限制&quot;">​</a></h3><p>剪贴板是全局操作系统级别的东西。用户可能会在各种应用程序之间切换，而浏览器页面不应该能访问这些内容</p><p>因此，大多数浏览器仅允许在某些用户操作范围内（例如复制/粘贴等）对剪切板进行无缝的读/写访问</p><p>除火狐（Firefox）浏览器外，所有浏览器都禁止使用 <code>dispatchEvent</code> 生成自定义剪贴板事件，即使我们设法调度此类事件</p><p>此外，如果想将 <code>event.clipboardData</code> 保存在事件处理程序中，然后稍后再访问它，这也不会生效</p><p><code>event.clipboardData</code> 仅在用户启动的事件处理程序的上下文中生效</p><p>另外, <code>navigator.clipboard</code> 是一个较新的 API，适用于任何上下文。如果需要，它会请求用户的许可。火狐（Firefox）浏览器尚未支持</p><h2 id="_4-表单事件" tabindex="-1">4 表单事件 <a class="header-anchor" href="#_4-表单事件" aria-label="Permalink to &quot;4 表单事件&quot;">​</a></h2><h3 id="_4-1-submit-事件" tabindex="-1">4.1 submit 事件 <a class="header-anchor" href="#_4-1-submit-事件" aria-label="Permalink to &quot;4.1 submit 事件&quot;">​</a></h3><p><strong>提交表单主要有两种方式：</strong></p><ol><li>点击 <code>&lt;input type=&quot;submit&quot;&gt;</code> 或 <code>&lt;input type=&quot;image&quot;&gt;</code></li><li>在 <code>input</code> 字段中按下 <code>Enter</code> 键</li></ol><p><code>event.preventDefault()</code> 可以阻止表单提交</p><p><strong>submit 和 click 的关系：</strong></p><blockquote><p>在输入框中使用 Enter 发送表单时，会在 <code>&lt;input type=&quot;submit&quot;&gt;</code> 上触发一次 <code>click</code> 事件，实际上根本没有点击</p></blockquote><p>这是一个示例：</p>`,70),s("form",{onsubmit:"return false"},[s("input",{type:"text",size:"30",value:"Focus here and press enter"}),s("input",{type:"submit",value:"Submit",onclick:"alert('click')"})],-1),s("h3",{id:"_4-2-submit-方法",tabindex:"-1"},[a("4.2 submit 方法 "),s("a",{class:"header-anchor",href:"#_4-2-submit-方法","aria-label":'Permalink to "4.2 submit 方法"'},"​")],-1),s("p",null,[a("如果要手动将表单提交到服务器，我们可以调用 "),s("code",null,"form.submit()")],-1)])])}const h=e(t,[["render",c]]);export{m as __pageData,h as default};
